import os
import numpy as np

working_dir = os.path.join(os.getcwd(), "working")
data_path = os.path.join(working_dir, "experiment_data.npy")

if not os.path.exists(data_path):
    raise FileNotFoundError(f"Experiment data not found at {data_path}")

# Load the experiment data
experiment_data = np.load(data_path, allow_pickle=True).item()

print("Analyzing Experiment Results:\n")

for cond_name, cond_data in experiment_data.items():
    if "metrics" not in cond_data:
        continue

    metrics = cond_data["metrics"]

    print(f"Condition: {cond_name}")

    # Extract and print specific metrics defined in summarize_failures
    mean_pair_failure_correlation = metrics.get("mean_pair_failure_correlation")
    n_eff_var = metrics.get("n_eff_var")
    n_eff_all = metrics.get("n_eff_all")
    mean_failure_rate = metrics.get("mean_failure_rate")

    # Print labels clearly as requested
    if mean_failure_rate is not None:
        print(f"  Mean Failure Rate: {mean_failure_rate:.4f}")

    if mean_pair_failure_correlation is not None:
        print(f"  Mean Pair Failure Correlation: {mean_pair_failure_correlation:.4f}")
    else:
        print(f"  Mean Pair Failure Correlation: N/A")

    if n_eff_var is not None:
        print(
            f"  Effective Independent Ensemble Size (Variance-based): {n_eff_var:.4f}"
        )
    else:
        print(f"  Effective Independent Ensemble Size (Variance-based): N/A")

    if n_eff_all is not None:
        print(
            f"  Effective Independent Ensemble Size (All-Wrong Probability-based): {n_eff_all:.4f}"
        )
    else:
        print(
            f"  Effective Independent Ensemble Size (All-Wrong Probability-based): N/A"
        )

    print("")

