import matplotlib.pyplot as plt
import numpy as np
import os

working_dir = os.path.join(os.getcwd(), "working")
os.makedirs(working_dir, exist_ok=True)

try:
    experiment_data = np.load(
        os.path.join(working_dir, "experiment_data.npy"), allow_pickle=True
    ).item()
except Exception as e:
    print(f"Error loading experiment data: {e}")
    exit()

# Plot 1: n_eff_var Comparison
try:
    labels = []
    values = []
    for cond_name, cond_data in experiment_data.items():
        for gain_key, gain_data in cond_data.items():
            if isinstance(gain_data, dict) and "metrics" in gain_data:
                neff = gain_data["metrics"].get("n_eff_var")
                if neff is not None:
                    labels.append(f"{cond_name}\n{gain_key}")
                    values.append(neff)

    if labels:
        plt.figure(figsize=(12, 6))
        bars = plt.bar(range(len(labels)), values, color="skyblue", edgecolor="black")
        plt.xticks(range(len(labels)), labels, rotation=45, ha="right", fontsize=8)
        plt.ylabel("Effective Independent Ensemble Size (n_eff_var)")
        plt.title(
            "Comparison of Effective Independent Ensemble Size Across Conditions and Gains"
        )
        plt.tight_layout()
        plt.savefig(os.path.join(working_dir, "ensemble_n_eff_var_comparison.png"))
        plt.close()
except Exception as e:
    print(f"Error creating plot1: {e}")
    plt.close()

# Plot 2: Mean Pair Failure Correlation
try:
    labels = []
    values = []
    for cond_name, cond_data in experiment_data.items():
        for gain_key, gain_data in cond_data.items():
            if isinstance(gain_data, dict) and "metrics" in gain_data:
                corr = gain_data["metrics"].get("mean_pair_failure_correlation")
                if corr is not None:
                    labels.append(f"{cond_name}\n{gain_key}")
                    values.append(corr)

    if labels:
        plt.figure(figsize=(12, 6))
        bars = plt.bar(range(len(labels)), values, color="salmon", edgecolor="black")
        plt.xticks(range(len(labels)), labels, rotation=45, ha="right", fontsize=8)
        plt.ylabel("Mean Pair Failure Correlation")
        plt.title("Correlation of Errors Between Ensemble Members")
        plt.axhline(y=0, color="k", linestyle="-")
        plt.tight_layout()
        plt.savefig(os.path.join(working_dir, "failure_correlation_comparison.png"))
        plt.close()
except Exception as e:
    print(f"Error creating plot2: {e}")
    plt.close()

# Plot 3: Average Training Loss Curves per Condition (aggregated over members)
try:
    # Collect average loss curve for each condition/gain combo
    all_loss_curves = {}
    max_epochs = 0

    for cond_name, cond_data in experiment_data.items():
        for gain_key, gain_data in cond_data.items():
            if isinstance(gain_data, dict) and "losses" in gain_data:
                losses_list = gain_data["losses"]
                if losses_list and len(losses_list) > 0:
                    # Calculate mean loss per epoch across members
                    num_members = len(losses_list)
                    num_epochs = len(losses_list[0])
                    if num_epochs > 0:
                        mean_losses = [
                            np.mean([l[i] for l in losses_list])
                            for i in range(num_epochs)
                        ]
                        key_label = f"{cond_name}_{gain_key}"
                        all_loss_curves[key_label] = mean_losses
                        max_epochs = max(max_epochs, num_epochs)

    if all_loss_curves:
        plt.figure(figsize=(10, 6))
        for label, losses in all_loss_curves.items():
            plt.plot(losses, label=label, linewidth=2)

        plt.xlabel("Epoch")
        plt.ylabel("Average Training Loss")
        plt.title("Training Loss Convergence by Condition and Gain")
        plt.legend(loc="upper right", bbox_to_anchor=(1.15, 1), fontsize=8)
        plt.grid(True, linestyle="--", alpha=0.7)
        plt.tight_layout()
        plt.savefig(os.path.join(working_dir, "training_loss_curves.png"))
        plt.close()
except Exception as e:
    print(f"Error creating plot3: {e}")
    plt.close()

