import os
import numpy as np

working_dir = os.path.join(os.getcwd(), "working")
data_path = os.path.join(working_dir, "experiment_data.npy")

if not os.path.exists(data_path):
    raise FileNotFoundError(f"Data file not found at {data_path}")

experiment_data = np.load(data_path, allow_pickle=True).item()

best_n_eff = -float("inf")
best_config = None

print("Analyzing Experiment Data:\n")

for cond_name, gains_dict in experiment_data.items():
    for gain_key, exp_result in gains_dict.items():
        metrics = exp_result.get("metrics", {})

        # Extract specific metrics
        n_eff_var = metrics.get("n_eff_var")
        n_eff_all = metrics.get("n_eff_all")
        mean_pair_corr = metrics.get("mean_pair_failure_correlation")
        mean_acc = (
            np.mean(metrics.get("member_accuracy", []))
            if metrics.get("member_accuracy")
            else None
        )

        full_label = f"{cond_name}_{gain_key}"

        print(f"Dataset: {full_label}")
        if mean_acc is not None:
            print(f"  Mean Member Accuracy: {mean_acc:.4f}")
        if mean_pair_corr is not None:
            print(f"  Mean Pair Failure Correlation: {mean_pair_corr:.4f}")
        if n_eff_var is not None:
            print(f"  N_eff (variance method): {n_eff_var:.4f}")
        if n_eff_all is not None:
            print(f"  N_eff (all-wrong method): {n_eff_all:.4f}")

        # Determine best based on sum of n_effs or just variance method as primary
        current_score = 0.0
        if n_eff_var is not None:
            current_score += n_eff_var
        if n_eff_all is not None:
            current_score += n_eff_all

        if current_score > best_n_eff:
            best_n_eff = current_score
            best_config = full_label
            best_metrics = {"n_eff_var": n_eff_var, "n_eff_all": n_eff_all}
        print("-" * 30)

print("\n=== Summary ===")
if best_config:
    print(f"Best Configuration: {best_config}")
    if best_metrics["n_eff_var"] is not None:
        print(
            f"FINAL EFFECTIVE_INDEPENDENT_ENSEMBLE_SIZE (variance): {best_metrics['n_eff_var']:.4f}"
        )
    if best_metrics["n_eff_all"] is not None:
        print(
            f"FINAL EFFECTIVE_INDEPENDENT_ENSEMBLE_SIZE (all-wrong): {best_metrics['n_eff_all']:.4f}"
        )
else:
    print("No valid metrics found.")

